from collections import Counter
def transform(grid):
    g=[r[:] for r in grid]
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    minor=[c for c in cnt if c!=bg][0]
    for r in g:
        for i in range(len(r)-2):
            if r[i]==minor and r[i+1]==bg and r[i+2]==minor:
                r[i+1]=2
    return g
